//! File-summary task prompts.
//!
//! Canonical since 2026-09-13. Originally GENERATED by
//! `tools/gen_rust_prompts.py` from `references/eval/tasks_prompts.py`; the
//! Python module and the generator were retired with the Python runtime
//! (ddb7d53) and these constants are now the source of truth.
//!
//! WHAT GUARANTEES THIS TEXT, since the gate these headers used to cite
//! (`references/tests/test_rust_prompt_parity.py`) died with the Python harness:
//!   * the file list is pinned ROW FOR ROW and every row is checked against the
//!     working tree AND against a fresh clone's file list, by
//!     `the_file_summary_prompts_wrap_one_pinned_file_list` in `mod.rs`;
//!   * this family is pinned by CONTENT, not derived from production:
//!     `conf/prompts.toml` has no `[file_summary]` table at all (asserted by
//!     `only_the_twitter_family_is_shared_with_production`), so unlike TWITTER
//!     there is no production text here to drift away from. Regenerating means
//!     editing these constants and the pin together, deliberately.
//!
//! WHY THE LIST IS SHORTER THAN IT WAS (2026-10-04): 16 of the 28 rows were
//! `references/**` paths that ddb7d53 deleted, and `pyproject.toml` is real but
//! UNTRACKED, so a fresh clone has none of it.
//!
//! WHAT REPLACED THEM: the rows that stood for "the Python tree" now stand for
//! the Rust tree, whose module names mislead in the same way and for the same
//! reason — `manifest.rs` is path helpers, `units.rs` is narrowing casts,
//! `image_renamer.rs` is a shim over `rename/`. A row with an honest name adds
//! nothing here, so the docs and config rows stay and the source rows are the
//! ones that carry the anti-inference test.
//!
//! THE FILES ARE NOW SENT, NOT JUST NAMED (2026-10-05). Until this commit the
//! prompt carried seventeen absolute paths and nothing else, while instructing
//! "Rely ONLY on provided content context ... DO NOT infer functionality from
//! file names". There was no content to rely on and no tool to fetch it with,
//! so the rule was unfollowable as written and the scorer counted verb-shaped
//! sentences instead of grounded ones. [`FILE_SUMMARY_CONTENTS_SLOT`] is where
//! [`content::excerpts`] is spliced in; the bound that keeps it inside a token
//! budget is [`FILE_SUMMARY_EXCERPT_LINES`] / [`FILE_SUMMARY_EXCERPT_BYTES`],
//! and the rows' TRUTH is [`FILE_SUMMARY_GROUND_TRUTH`] — the scorer grades a
//! description against what its file says, so it needs to know what that is.

#[path = "file_summary_content.rs"]
mod content;

pub use content::{excerpt, excerpts, render, render_both, substitute};

/// Where the per-file content block goes, in both templates.
///
/// Deliberately BEFORE the mixed prompt's noise block:
/// `validate_mixed_file_summary` splits the source on the noise marker and reads
/// signal paths out of everything above it, so content placed after the marker
/// would be read as noise.
///
/// [`FILE_SUMMARY_EXCERPT_LINES`] and [`FILE_SUMMARY_EXCERPT_BYTES`] bound it.
///
/// [`FILE_SUMMARY_EXCERPT_BYTES`]: FILE_SUMMARY_EXCERPT_BYTES
/// [`FILE_SUMMARY_EXCERPT_LINES`]: FILE_SUMMARY_EXCERPT_LINES
pub const FILE_SUMMARY_CONTENTS_SLOT: &str = "<<<FILE CONTENTS>>>";

/// Lines of each file sent.
///
/// The module doc comment comes first in every Rust file here and the config
/// files lead with their keys and their own NOTE, so the head of the file is where
/// "what it does" is written. `docs/MODEL_QUIRKS.md` is 1300 lines; the whole
/// file is 65KB and would be two thirds of the prompt.
pub const FILE_SUMMARY_EXCERPT_LINES: usize = 40;

/// Byte ceiling per file, which binds before the line count does on a file with
/// long lines.
///
/// Stated as a byte bound because the budget it protects is a token budget, and
/// 1200 bytes is about 300 tokens.
pub const FILE_SUMMARY_EXCERPT_BYTES: usize = 1200;

/// Per-row ground truth: what each listed file actually contains, in phrases a
/// competent reader would use and a NAME GUESS CANNOT.
///
/// Keyed repo-relative (the prefix is not a property of the answer, and models
/// echo bare basenames). The scorer in `super::validate` looks a row up by
/// suffix, so `units.rs`, `rust/src/units.rs` and the absolute path all resolve.
///
/// Two phrases per row, and the scorer demands one of the two — so a row is
/// cleared by naming something only its content says.
///
/// Three properties are pinned, not assumed, by `validate_grounding_tests.rs`:
///
///   * every phrase still occurs in its file,
///   * no name-derived sentence clears any row,
///   * every description written from the content clears its row.
///
/// A phrase with a single identifying token is still allowed — `tesseract` is one
/// token and no sentence about `rename.toml` contains it. A phrase whose tokens
/// are all shorter than four characters is not: `llm url` has none, and a phrase
/// nothing can match is a phrase nothing can clear.
///
/// WHY HAND-PINNED rather than re-derived from the file at scoring time: a
/// validator that re-reads the working tree makes a leaderboard score depend on
/// the tree at SCORING time rather than at PROMPT-BUILD time, so two runs of the
/// same commit could disagree. This is the same hand-pinned-facts shape the
/// tweet tasks already use (`KEY_FACTS` + `validate_factual_coverage`).
pub const FILE_SUMMARY_GROUND_TRUTH: &[(&str, &[&str])] = &[
    (
        "README.md",
        &["twitter timeline summarization", "family weekend planning"],
    ),
    ("CLAUDE.md", &["file size limit", "coverage floor"]),
    ("conf/config.toml", &["max tokens budget", "best models"]),
    (
        "conf/weekend.toml",
        &["exclude places", "top-level keys must precede"],
    ),
    (
        "conf/twitter.toml",
        &["chrome cookies db", "state file output directory"],
    ),
    ("conf/rename.toml", &["tesseract", "mlx models directory"]),
    (
        "conf/models/foundation.toml",
        &["context window", "max tokens cap"],
    ),
    (
        "conf/models/gemma.toml",
        &["field mapping", "prompt schema"],
    ),
    ("conf/models/qwen.toml", &["field mapping", "prompt schema"]),
    ("docs/MODEL_QUIRKS.md", &["duckduckgo", "search engines"]),
    ("docs/TESTING.md", &["golden parity", "structural gates"]),
    ("rust/src/manifest.rs", &["leading tilde", "home directory"]),
    (
        "rust/src/units.rs",
        &["saturating conversions", "whole milliseconds"],
    ),
    (
        "rust/src/ztools/image_renamer.rs",
        &["shim re-exporting", "split rename package"],
    ),
    (
        "rust/src/ztools/store.rs",
        &["newest dated plan", "weekend store dir"],
    ),
    (
        "rust/src/ztools/twitter/mod.rs",
        &["browser collection module", "cookies"],
    ),
    (
        "rust/src/ztools/weekend/format.rs",
        &["section headings", "why it fits"],
    ),
];

